+  const grid=new Map();
+  for(let i=0;i<bodies.length;i++){
+    const b=bodies[i];
+    const x0=Math.floor(b.minX/CELL), x1=Math.floor(b.maxX/CELL);
+    const y0=Math.floor(b.minY/CELL), y1=Math.floor(b.maxY/CELL);
+    for(let gx=x0;gx<=x1;gx++) for(let gy=y0;gy<=y1;gy++){
