+  state="settled";
+  setStatus("SETTLED","done");
+  // Outcome summary measured from the simulation, not scripted.
+  let fallen=0;
+  for(const b of bricks){
+    const tipped=Math.abs(Math.sin(b.a))>0.35;
+    if(tipped || b.y < (FIXED.brickH/2)+0.05 && b.x>WALL_X+ (settings.wallCols*FIXED.brickW)+1.2) fallen++;
