+  ctx.strokeStyle="rgba(232,161,58,0.65)"; ctx.lineWidth=2; ctx.setLineDash([6,6]);
+  ctx.beginPath(); ctx.moveTo(WALL_X*S,groundY); ctx.lineTo(WALL_X*S,groundY-(settings.wallRows*FIXED.brickH+0.7)*S); ctx.stroke();
+  ctx.setLineDash([]);
+  ctx.fillStyle="rgba(232,161,58,0.9)"; ctx.font=(0.18*S)+"px "+getMono(); ctx.textAlign="left";
