+  ctx.lineTo(rear+0.06*S, belt-0.10*S);
+  ctx.lineTo(-W*0.18, belt-0.10*S);
+  ctx.lineTo(-W*0.02, roof+0.10*S);          // rear glass up to roof
+  ctx.lineTo( W*0.20, roof+0.08*S);
+  ctx.lineTo( W*0.34, belt-0.06*S);          // windscreen down
+  ctx.lineTo(front-0.08*S, belt+0.02*S);     // bonnet
