+  slowMo=!slowMo;
+  e.currentTarget.setAttribute("aria-pressed",String(slowMo));
+  e.currentTarget.textContent=slowMo?"Normal speed":"Slow motion";
+});
+window.addEventListener("keydown",e=>{
+  if(e.target.tagName==="INPUT") return;
+  if(e.code==="Space"||e.code==="Enter"){ e.preventDefault(); launch(); }
+  if(e.key==="r"||e.key==="R") buildScene();
+});
+
+/* Boot: show the default car and wall before any test. */
