+      const x=front-(0.10+i*0.14)*S*(1+carCrush*2);
+      ctx.beginPath(); ctx.moveTo(x,belt+0.02*S); ctx.lineTo(x-0.06*S,base-0.32*S); ctx.stroke();
+    }
+  }
+  // Glasshouse.
+  ctx.beginPath();
+  ctx.moveTo(-W*0.15,belt-0.12*S); ctx.lineTo(-W*0.01,roof+0.16*S);
+  ctx.lineTo(W*0.18,roof+0.14*S); ctx.lineTo(W*0.30,belt-0.10*S); ctx.closePath();
+  ctx.fillStyle="#b9d2e8"; ctx.fill();
+  ctx.strokeStyle="#20344d"; ctx.lineWidth=Math.max(2,0.045*S);
+  ctx.beginPath(); ctx.moveTo(W*0.07,roof+0.14*S); ctx.lineTo(W*0.07,belt-0.11*S); ctx.stroke();
+  // Door shut-lines, handle, lights.
+  ctx.strokeStyle="rgba(10,18,30,0.55)"; ctx.lineWidth=Math.max(1,0.018*S);
+  ctx.strokeRect(-W*0.16,belt-0.08*S,W*0.20,0.62*S);
+  ctx.fillStyle="#f5d67a"; ctx.fillRect(front-0.14*S,belt+0.08*S,0.12*S,0.13*S);
+  ctx.fillStyle="#c23b2e"; ctx.fillRect(rear+0.02*S,belt+0.08*S,0.09*S,0.13*S);
+  ctx.fillStyle="rgba(255,255,255,0.20)"; ctx.fillRect(rear,belt-0.02*S,front-rear,0.07*S);
+  // Wheels.
+  const wr=0.33*S, wy=base-wr+0.02*S;
+  for(const wx of [-W*0.32, W*0.32-crush*0.35]){
+    ctx.fillStyle="#14161a"; ctx.beginPath(); ctx.arc(wx,wy,wr,0,7); ctx.fill();
+    ctx.fillStyle="#9aa3ad"; ctx.beginPath(); ctx.arc(wx,wy,wr*0.52,0,7); ctx.fill();
+    ctx.strokeStyle="#3c424b"; ctx.lineWidth=Math.max(1.5,0.03*S);
+    for(let k=0;k<5;k++){
+      const a=wheelAngle+k*Math.PI*2/5;
+      ctx.beginPath(); ctx.moveTo(wx,wy);
+      ctx.lineTo(wx+Math.cos(a)*wr*0.5, wy+Math.sin(a)*wr*0.5); ctx.stroke();
+    }
+  }
+  // Motion streaks while launching.
+  if(state==="running" && !carHasHit && Math.abs(b.vx)>6){
+    ctx.strokeStyle="rgba(255,255,255,0.35)"; ctx.lineWidth=Math.max(1,0.025*S);
+    for(const off of [-0.30,0.05,0.38]){
+      ctx.beginPath(); ctx.moveTo(rear-0.15*S, off*S);
+      ctx.lineTo(rear-(0.55+Math.abs(b.vx)*0.02)*S, off*S); ctx.stroke();
+    }
+  }
+  ctx.restore();
+}
+function draw(){
+  ctx.setTransform(dpr,0,0,dpr,0,0);
+  const S=renderScale();
+  const groundY=viewH-1.15*S;
+  ctx.save();
+  if(shake>0.004){
+    const t=performance.now()*0.09;
+    ctx.translate(Math.sin(t*1.7)*shake*S, Math.cos(t*2.3)*shake*S*0.7);
+  }
+  drawBackground(S,groundY);
+  drawGround(S,groundY);
+  // Back depth layers first so the front face reads clearly.
+  const sorted=bricks.slice().sort((p,q)=>q.layer-p.layer);
+  for(const b of sorted) drawBrick(b,S,groundY);
+  drawCar(S,groundY);
+  // Dust.
+  for(const p of particles){
+    const k=1-p.age/p.life;
+    ctx.fillStyle="rgba(196,178,150,"+(0.34*k)+")";
+    ctx.beginPath(); ctx.arc(p.x*S,groundY-p.y*S,p.r*S*(1.6-k*0.6),0,7); ctx.fill();
+  }
+  ctx.restore();
+  // Scale caption.
+  ctx.fillStyle="rgba(255,255,255,0.55)";
+  ctx.font="11px "+getMono(); ctx.textAlign="right";
+  ctx.fillText(S.toFixed(0)+" px/m · "+bodies.length+" bodies", viewW-10, viewH-8);
+}
+
+/* ============================================================
+   Main loop — fixed-step physics (240 Hz substeps) so fast
+   impacts cannot tunnel through a 0.50 m brick.
+   ============================================================ */
+let lastTs=0, accumulator=0;
+const STEP=1/240;
+function frame(ts){
+  requestAnimationFrame(frame);
+  if(!lastTs) lastTs=ts;
+  let dt=Math.min((ts-lastTs)/1000, 0.05); lastTs=ts;
+  if(slowMo) dt*=0.22;
+  if(state==="running"){
+    accumulator+=dt;
+    let n=0;
+    while(accumulator>=STEP && n<40){ stepPhysics(STEP); accumulator-=STEP; n++; }
+    if(n>=40) accumulator=0;
+    updateHud();
+  }
+  draw();
+}
+
+/* ============================================================
+   UI wiring
+   ============================================================ */
+const $=id=>document.getElementById(id);
+function setStatus(txt,cls){ const p=$("statusPill"); p.textContent=txt; p.className=cls||""; p.id="statusPill"; }
+function movingBrickCount(){
+  let n=0; for(const b of bricks) if(!b.asleep && Math.hypot(b.vx,b.vy)>0.08) n++;
+  return n;
+}
+function updateHud(){
+  if(!car) return;
+  const sp=Math.hypot(car.vx,car.vy);
+  $("hudSpeed").textContent=sp.toFixed(1)+" m/s ("+(sp*3.6).toFixed(0)+" km/h)";
+  $("hudTime").textContent=simTime.toFixed(2)+" s";
+  $("hudMoving").textContent=movingBrickCount()+" / "+bricks.length;
+  $("hudMom").textContent=Math.round(FIXED.carMass*sp).toLocaleString("en-GB")+" kg·m/s";
+  $("hudPeak").textContent=(impactPeakN/1000).toFixed(0)+" kN";
+}
+const ctlRefs={};
+function buildControls(){
+  const host=$("controls"); host.innerHTML="";
+  for(const key of Object.keys(RANGES)){
+    const r=RANGES[key];
+    const div=document.createElement("div"); div.className="ctl";
+    div.innerHTML=
+      '<div class="row"><label for="rng-'+key+'">'+r.label+' <span class="unit">'+r.unit+'</span></label>'+
+      '<output id="out-'+key+'"></output></div>'+
+      '<input type="range" id="rng-'+key+'" min="'+r.min+'" max="'+r.max+'" step="'+r.step+'">'+
+      '<div class="row"><span class="range" style="flex:1"><span>'+r.min+'</span><span>'+r.max+'</span></span>'+
+      '<input type="number" id="num-'+key+'" min="'+r.min+'" max="'+r.max+'" step="'+r.step+'" aria-label="'+r.label+' value"></div>';
+    host.appendChild(div);
+    const rng=div.querySelector("#rng-"+key), num=div.querySelector("#num-"+key), out=div.querySelector("#out-"+key);
+    ctlRefs[key]={rng,num,out};
+    const apply=(raw)=>{
+      let v=clamp(parseFloat(raw), r.min, r.max);
+      if(!isFinite(v)) return;
+      if(r.step>=1) v=Math.round(v);
+      settings[key]=v;
+      rng.value=v; num.value=v; out.textContent=r.fmt(v)+" "+r.unit.split(" ")[0];
+      buildScene(); // rebuild preview with this change only
+    };
+    rng.addEventListener("input",()=>apply(rng.value));
+    num.addEventListener("change",()=>apply(num.value));
+  }
+  syncControls();
+}
+function syncControls(){
+  for(const key of Object.keys(RANGES)){
+    const r=RANGES[key], c=ctlRefs[key]; if(!c) continue;
+    c.rng.value=settings[key]; c.num.value=settings[key];
+    c.out.textContent=r.fmt(settings[key])+" "+r.unit.split(" ")[0];
+  }
+}
+$("fixedParams").innerHTML=
+  "Fixed baseline parameters<br>"+
+  "brick size <b>0.50 × 0.24 m</b> · gravity <b>9.81 m/s²</b><br>"+
+  "brick friction <b>0.72</b> · restitution <b>0.18</b><br>"+
+  "car <b>1,250 kg</b> · <b>4.2 × 1.45 m</b><br>"+
+  "ground friction <b>0.85</b> · scale <b>80 px/m</b> (max)";
+$("testBtn").addEventListener("click",launch);
+$("resetBtn").addEventListener("click",()=>buildScene());
+$("defaultsBtn").addEventListener("click",()=>{
+  Object.assign(settings,DEFAULTS); syncControls(); buildScene();
+});
+$("slowBtn").addEventListener("click",e=>{
+  slowMo=!slowMo;
+  e.currentTarget.setAttribute("aria-pressed",String(slowMo));
+  e.currentTarget.textContent=slowMo?"Normal speed":"Slow motion";
+});
+window.addEventListener("keydown",e=>{
+  if(e.target.tagName==="INPUT") return;
+  if(e.code==="Space"||e.code==="Enter"){ e.preventDefault(); launch(); }
+  if(e.key==="r"||e.key==="R") buildScene();
+});
+
+/* Boot: show the default car and wall before any test. */
+resize();
+buildControls();
+buildScene();
+requestAnimationFrame(frame);
+</script>
+</body>
+</html>

